import{_ as p,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Redirects - October CMS - 4.x","titleTemplate":false,"description":"Learn how to redirect to another page or URL.","frontmatter":{"subtitle":"Learn how to redirect to another page or URL."},"headers":[{"level":2,"title":"Redirecting to a CMS Page","slug":"redirecting-to-a-cms-page","link":"#redirecting-to-a-cms-page","children":[]},{"level":2,"title":"Redirects in Twig","slug":"redirects-in-twig","link":"#redirects-in-twig","children":[]},{"level":2,"title":"Redirects in AJAX","slug":"redirects-in-ajax","link":"#redirects-in-ajax","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/features/redirects.md","filePath":"4.x/cms/features/redirects.md"}'),u={name:"4.x/cms/features/redirects.md"};function r(k,a,d,g,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"Redirects",-1)),s(e),a[1]||(a[1]=i(`<p>In some cases you may wish to redirect the user to a new page after submitting a form, or any AJAX request.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSignup<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Email<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Sign Up
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Inside your <a href="./../../ajax/handlers.html">AJAX handler</a>, you may return a <code>Redirect</code> <a href="./../../extend/services/response-view.html">response type</a> where the <code>to</code> method accepts a relative or absolute URL (first argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/signup-complete&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may use the <code>refresh</code> method to refresh the current page. The use of <a href="./flash-messages.html">flash messages</a> is also supported.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Signup complete!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="redirecting-to-a-cms-page"><a href="#redirecting-to-a-cms-page" class="header-anchor">#</a> Redirecting to a CMS Page</h2><p>The <code>Cms</code> facade and <code>redirect</code> method can be used to redirect to specific CMS page (first argument) and any optional route parameters (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">redirect</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blog/post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;foobar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may use the <code>pageUrl</code> method to return the URL as a string instead.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$postPage</span> <span class="token operator">=</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">pageUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blog/post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;foobar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="redirects-in-twig"><a href="#redirects-in-twig" class="header-anchor">#</a> Redirects in Twig</h2><p>The <a href="./../../markup/function/redirect.html"><code>redirect()</code> Twig function</a> can be used to redirect the user from within the page markup.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSignup</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;success&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>This function accepts a URL or a CMS page name.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> success <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> redirect<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>/signup-complete<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="redirects-in-ajax"><a href="#redirects-in-ajax" class="header-anchor">#</a> Redirects in AJAX</h2><p>The <a href="./../../ajax/introduction.html">AJAX framework</a> supports redirects with the <code>data-request-redirect</code> attribute. The attribute value should specify a URL location to redirect after a successful AJAX request completes.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-redirect</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/signup-complete<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Save and Redirect
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The <a href="./../../ajax/turbo-router.html">turbo router</a> supports historical redirects with the <code>data-browser-redirect-back</code> attribute. The attribute can be attached to any hyperlink or AJAX request element, overriding a redirect response, and only triggers when there is a previous browser history state.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRedirect<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-browser-redirect-back</span><span class="token punctuation">&gt;</span></span>
    Save and Back
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The attribute value can also be used on hyperlinks.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/home<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-browser-redirect-back</span><span class="token punctuation">&gt;</span></span>
    Go Back
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block warning"><p>The <code>data-browser-redirect-back</code> attribute should be used in combination with a traditional redirect as fallback location.</p></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../markup/function/redirect.html">Redirect Twig function</a></li><li><a href="./../../extend/services/response-view.html">Responses and Views</a></li></ul></div>`,26))])}const w=p(u,[["render",r]]);export{v as __pageData,w as default};
